end

__bundleFactories["CustomHub.Features.TeleportFeature"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/TeleportFeature.lua
local TeleportFeature = {
    Context = nil,
    MovementService = nil,
    ActiveTravel = nil,
    Generation = 0,
    CharacterRemovingConnection = nil,
}

local MAX_STALL_RETRIES = 2
local STALL_RETRY_DELAY = 1.1

local function disconnect(connection)
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
    end
end

local function currentSeaIndex(compatibility)
    local checks = {
        { Index = 1, Method = "IsFirstSea" },
        { Index = 2, Method = "IsSecondSea" },
        { Index = 3, Method = "IsThirdSea" },
    }
    local found
    local count = 0
    for _, sea in ipairs(checks) do
        local check = compatibility and compatibility[sea.Method]
        if type(check) == "function" then
            local ok, result = pcall(check, compatibility)
            if ok and result == true then
                found = sea.Index
                count += 1
            end
        end
    end
    return count == 1 and found or nil
end

function TeleportFeature:_SetStatus(message, kind)
    if self.Context and self.Context.State then
        self.Context.State:SetStatus(message, kind or "info")
    end
end

function TeleportFeature:IsTraveling()
    return self.ActiveTravel ~= nil
end

function TeleportFeature:_GetSelectedIsland()
    local compatibility = self.Context and self.Context.Compatibility
    local config = self.Context and self.Context.Config
    local seaIndex = currentSeaIndex(compatibility)
    if not seaIndex then
        return nil, "Could not identify the current sea"
    end

    local selected = config and config.TravelSettings and config.TravelSettings.Island
    if type(selected) ~= "string" then
        return nil, "Select an island first"
    end
    for _, destination in ipairs((config.TravelDestinations or {})[seaIndex] or {}) do
        if destination.Name == selected then
            return destination
        end
    end
    return nil, "That island is unavailable in this sea"
end

function TeleportFeature:_FindNpcRoot(name)
    local compatibility = self.Context and self.Context.Compatibility
    local workspace = compatibility and compatibility.Workspace
    local npcFolder = workspace and workspace:FindFirstChild("NPCs")
    if not npcFolder then
        return nil, "Workspace.NPCs is unavailable"
    end

    local _, _, playerRoot = compatibility:GetCharacterParts()
    local nearestRoot
    local nearestDistance = math.huge
    for _, npc in ipairs(npcFolder:GetChildren()) do
        if npc:IsA("Model") and npc.Name == name then
            local root = npc:FindFirstChild("HumanoidRootPart")
            local humanoid = npc:FindFirstChildOfClass("Humanoid")
            if root and root:IsA("BasePart") and (not humanoid or humanoid.Health > 0) then
                local distance = playerRoot and (root.Position - playerRoot.Position).Magnitude or 0
                if distance < nearestDistance then
                    nearestRoot = root
                    nearestDistance = distance
                end
            end
        end
    end
    if not nearestRoot then
        return nil, "The selected NPC is not currently loaded in Workspace.NPCs"
    end
    return nearestRoot
end

function TeleportFeature:_GetNpcDestination()
    local compatibility = self.Context and self.Context.Compatibility
    if not currentSeaIndex(compatibility) then
        return nil, "Could not identify the current sea"
    end
    local selected = self.Context.Config.TravelSettings.Npc
    if type(selected) ~= "string" then
        return nil, "Select an NPC first"
    end
    local root, rootError = self:_FindNpcRoot(selected)
    if not root then
        return nil, rootError
    end
    return CFrame.new(root.Position + Vector3.new(0, 5, 0))
end

function TeleportFeature:_ResolveIslandCFrame(destination)
    if destination.Position then
        return CFrame.new(destination.Position + Vector3.new(0, 18, 0))
    end
    if destination.LocationName then
        local workspace = self.Context.Compatibility.Workspace
        local worldOrigin = workspace:FindFirstChild("_WorldOrigin")
        local locations = worldOrigin and worldOrigin:FindFirstChild("Locations")
        local location = locations and locations:FindFirstChild(destination.LocationName)
        if location and location:IsA("BasePart") then
            return location.CFrame + Vector3.new(0, 18, 0)
        elseif location and location:IsA("Model") then
            return location:GetPivot() + Vector3.new(0, 18, 0)
        end
        return nil, "The selected location is not currently available"
    end
    return nil, "The selected island has no usable destination"
end

function TeleportFeature:_FinishTravel(request, message, kind)
    if self.ActiveTravel ~= request then
        return
    end
    self.ActiveTravel = nil
    self.Generation += 1
    if self.MovementService then
        self.MovementService:Cancel()
        self.MovementService:SetFarmCollisionSuppression(false)
    end
    self:_SetStatus(message, kind)
end

function TeleportFeature:Cancel(message)
    local request = self.ActiveTravel
    if not request then
        return false
    end
    self.ActiveTravel = nil
    self.Generation += 1
    if self.MovementService then
        self.MovementService:Cancel()
        self.MovementService:SetFarmCollisionSuppression(false)
    end
    if message then
        self:_SetStatus(message, "warning")
    else
        self:_SetStatus("Travel cancelled.", "info")
    end
    return true
end

function TeleportFeature:_StartTravel(destination, destinationLabel)
    local context = self.Context
    local compatibility = context and context.Compatibility
    local mainFarm = context and context.MainFarm
    if mainFarm and mainFarm.Running then
        self:_SetStatus("Turn off Start Farm before manual travel.", "warning")
        return false, "Auto Farm is running"
    end
    local character, humanoid, root = compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        self:_SetStatus("Travel unavailable: character is not ready.", "error")
        return false, "Character is unavailable"
    end

    if self.ActiveTravel then
        self:Cancel("Previous travel request cancelled.")
    end
    local collisionCallOk, collisionReady, collisionError = pcall(function()
        return self.MovementService:SetFarmCollisionSuppression(true)
    end)
    if not collisionCallOk then
        collisionError = collisionReady
        collisionReady = false
    end
    if not collisionReady then
        self:_SetStatus("Travel collision setup failed: " .. tostring(collisionError), "error")
        return false, collisionError
    end

    self.Generation += 1
    local request = {
        Generation = self.Generation,
        Character = character,
        StartedAt = os.clock(),
        LastStallAt = self.MovementService.LastStallAt,
        Label = destinationLabel,
        Destination = destination,
        StallRetries = 0,
    }
    self.ActiveTravel = request

    local function issueMovement()
        return self.MovementService:MoveTo(request.Destination, {
            Speed = 190,
            Threshold = 8,
            IsCurrent = function()
                return self.ActiveTravel == request
                    and self.Generation == request.Generation
                    and compatibility.Player.Character == character
                    and not (mainFarm and mainFarm.Running)
            end,
        })
    end
    local moveCallOk, moved, moveResult = pcall(issueMovement)
    if not moveCallOk then
        moveResult = moved
        moved = false
    end
    if not moved then
        self:_FinishTravel(
            request,
            "Travel could not start: " .. tostring(moveResult),
            "error"
        )
        return false, moveResult
    end
    if moveResult == "arrived" then
        self:_FinishTravel(request, "Arrived at " .. destinationLabel .. ".", "success")
        return true
    end

    self:_SetStatus("Travelling to " .. destinationLabel .. ".", "info")
    task.spawn(function()
        while self.ActiveTravel == request do
            if compatibility.Player.Character ~= character then
                self:_FinishTravel(request, "Travel cancelled because the character changed.", "warning")
                return
            end
            if mainFarm and mainFarm.Running then
                self:_FinishTravel(request, "Travel cancelled because Auto Farm started.", "warning")
                return
            end

            if not self.MovementService.Active then
                if self.MovementService.LastStallAt ~= request.LastStallAt then
                    request.LastStallAt = self.MovementService.LastStallAt
                    if request.StallRetries >= MAX_STALL_RETRIES then
                        self:_FinishTravel(
                            request,
                            "Travel stalled after "
                                .. tostring(request.StallRetries)
                                .. " retries; copy the status report for movement details, then try again.",
                            "warning"
                        )
                        return
                    end

                    request.StallRetries += 1
                    self:_SetStatus(
                        "Travel stalled; retrying ("
                            .. tostring(request.StallRetries)
                            .. "/"
                            .. tostring(MAX_STALL_RETRIES)
                            .. ").",
                        "warning"
                    )
                    task.wait(STALL_RETRY_DELAY)
                    if self.ActiveTravel ~= request then
                        return
                    end

                    local retryCallOk, retryMoved, retryResult = pcall(issueMovement)
                    if not retryCallOk then
                        retryResult = retryMoved
                        retryMoved = false
                    end
                    if not retryMoved then
                        self:_FinishTravel(
                            request,
                            "Travel retry could not start: " .. tostring(retryResult),
                            "error"
                        )
                        return
                    end
                    if retryResult == "arrived" then
                        self:_FinishTravel(
                            request,
                            "Arrived at " .. request.Label .. ".",
                            "success"
                        )
                        return
                    end
                else
                    self:_FinishTravel(request, "Arrived at " .. request.Label .. ".", "success")
                    return
                end
            end
            task.wait(0.1)
        end
    end)
    return true
end

function TeleportFeature:_SelectSetting(setting, value, validOptions)
    if type(value) ~= "string" then
        self:_SetStatus("Travel selection must be a destination name.", "error")
        return false, "Invalid selection"
    end
    for _, option in ipairs(validOptions) do
        if option == value then
            self.Context.Config.TravelSettings[setting] = value
            self:_SetStatus("Selected " .. value .. ".", "success")
            return true
        end
    end
    self:_SetStatus("That destination is not available in the current sea.", "warning")
    return false, "Destination is unavailable"
end

function TeleportFeature:Handle(actionId, payload)
    local config = self.Context and self.Context.Config
    if actionId == "teleport.island.select" then
        local compatibility = self.Context.Compatibility
        local seaIndex = currentSeaIndex(compatibility)
        local options = {}
        for _, destination in ipairs(
            seaIndex and (config.TravelDestinations[seaIndex] or {}) or {}
        ) do
            table.insert(options, destination.Name)
        end
        return self:_SelectSetting("Island", payload, options)
    elseif actionId == "teleport.npc.select" then
        local workspace = self.Context.Compatibility.Workspace
        local npcFolder = workspace and workspace:FindFirstChild("NPCs")
        local options = {}
        if currentSeaIndex(self.Context.Compatibility) and npcFolder then
            local names = {}
            for _, npc in ipairs(npcFolder:GetChildren()) do
                local root = npc:IsA("Model") and npc:FindFirstChild("HumanoidRootPart")
                local humanoid = npc:IsA("Model") and npc:FindFirstChildOfClass("Humanoid")
                if npc:IsA("Model")
                    and root
                    and root:IsA("BasePart")
                    and (not humanoid or humanoid.Health > 0)
                    and not string.find(npc.Name, "Boat", 1, true)
                    and not string.find(npc.Name, "Set Home", 1, true)
                then
                    names[npc.Name] = true
                end
            end
            for name in pairs(names) do
                table.insert(options, name)
            end
            table.sort(options)
        end
        return self:_SelectSetting("Npc", payload, options)
    elseif actionId == "teleport.island.go" then
        local destination, destinationError = self:_GetSelectedIsland()
        if not destination then
            self:_SetStatus(destinationError .. ".", "warning")
            return false, destinationError
        end
        local cframe, resolveError = self:_ResolveIslandCFrame(destination)
        if not cframe then
            self:_SetStatus(resolveError .. ".", "warning")
            return false, resolveError
        end
        return self:_StartTravel(cframe, destination.Name)
    elseif actionId == "teleport.npc.go" then
        local destination, destinationError = self:_GetNpcDestination()
        if not destination then
            self:_SetStatus(destinationError .. ".", "warning")
            return false, destinationError
        end
        return self:_StartTravel(destination, "NPC " .. tostring(config.TravelSettings.Npc))
    elseif actionId == "teleport.cancel" then
        if not self:Cancel() then
            self:_SetStatus("There is no active travel to cancel.", "info")
        end
        return true
    end
    return false
end

function TeleportFeature:Initialize(context)
    self:Cleanup()
    self.Context = context
    self.Generation = 0
    self.ActiveTravel = nil
    self.MovementService = context.MovementService

    local player = context.Compatibility.Player
    if player then
        self.CharacterRemovingConnection = player.CharacterRemoving:Connect(function()
            self:Cancel("Travel cancelled because the character is resetting.")
        end)
    end
    return true
end

function TeleportFeature:Cleanup()
    self:Cancel("Travel cancelled during hub cleanup.")
    disconnect(self.CharacterRemovingConnection)
    self.CharacterRemovingConnection = nil
    self.Context = nil
    self.MovementService = nil
end

return TeleportFeature
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/TeleportFeature.lua
end

__bundleFactories["CustomHub.Features.Farm.QuestService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
local QuestService = {}
QuestService.__index = QuestService

local MAX_TRACKED_QUEST_TEXT_LENGTH = 160
local MAX_TRACKED_QUEST_PROGRESS_LENGTH = 32
local MAX_MAIN_QUEST_TITLE_LENGTH = 160

local excludedQuestNames = {
    BartiloQuest = true,
    Trainees = true,
    MarineQuest = true,
    CitizenQuest = true,
}

local function diagnosticScalarRepresentation(value)
    local valueType = typeof(value)
    if type(value) == "string" then
        return string.format("<string length=%d>", #value)
    end

    if value == nil or type(value) == "boolean" then
        return tostring(value)
    end
    if type(value) == "number" then
        return "<number-redacted>"
    end
    return "<" .. tostring(valueType) .. ">"
end

local function usableTrackedQuestText(text, maxLength)
    if type(text) ~= "string" or #text == 0 or #text > maxLength then
        return nil
    end

    local trimmed = text:match("^%s*(.-)%s*$")
    if trimmed == "" then
        return nil
    end
    return trimmed
end

local function singularizeQuestTargetWord(word)
    if #word > 3 and word:sub(-3) == "ies" then
        local stem = word:sub(1, -4)
        local lastStemCharacter = stem:sub(-1)
        if lastStemCharacter ~= "" and not lastStemCharacter:match("[aeiou]") then
            return stem .. "y"
        end
    end

    if #word > 4 and word:sub(-2) == "es" then
        local stem = word:sub(1, -3)
        if stem:sub(-1) == "s" or stem:sub(-1) == "x" or stem:sub(-1) == "z"
            or stem:sub(-2) == "ch" or stem:sub(-2) == "sh"
        then
            return stem
        end
    end

    local ending = word:sub(-2)
    if #word > 2 and word:sub(-1) == "s"
        and ending ~= "ss" and ending ~= "us" and ending ~= "is"
    then
        return word:sub(1, -2)
    end
    return word
end

local function normalizeQuestTargetName(name)
    if type(name) ~= "string" or #name == 0 or #name > MAX_TRACKED_QUEST_TEXT_LENGTH then
        return nil
    end

    local words = {}
    for word in name:lower():gmatch("[%w]+") do
        table.insert(words, word)
    end
    if #words == 0 then
        return nil
    end

    words[#words] = singularizeQuestTargetWord(words[#words])
    return table.concat(words, " ")
end

local function trackedTargetMatches(catalogTarget, trackedTarget, allowFirstSeaVariants)
    if catalogTarget == trackedTarget then
        return true
    end
    if not allowFirstSeaVariants then
        return false
    end

    local normalizedCatalogTarget = normalizeQuestTargetName(catalogTarget)
    local normalizedTrackedTarget = normalizeQuestTargetName(trackedTarget)
    return normalizedCatalogTarget ~= nil
        and normalizedCatalogTarget == normalizedTrackedTarget
end

local function isVisibleGuiObjectWithin(instance, root)
    if not instance or not instance:IsA("GuiObject") then
        return false
    end

    local current = instance
    while current and current ~= root do
        if current:IsA("GuiObject") and not current.Visible then
            return false
        end
        if current:IsA("ScreenGui") and not current.Enabled then
            return false
        end
        current = current.Parent
    end
    return current == root
end

local function parseTrackedQuestProgress(text)
    if type(text) ~= "string" or #text > MAX_TRACKED_QUEST_PROGRESS_LENGTH then
        return nil
    end

    local currentText, totalText = text:match("^%s*(%d+)%s*/%s*(%d+)%s*$")
    if not currentText or not totalText then
        return nil
    end

    local current = tonumber(currentText)
    local total = tonumber(totalText)
    if not current or not total
        or current == math.huge
        or total == math.huge
        or total <= 0
        or current >= total
    then
        return nil
    end
    return current, total
end

local function titleContainsTarget(title, targetName, allowFirstSeaVariants)
    if type(title) ~= "string" or type(targetName) ~= "string" then
        return false
    end

    local titleWords = {}
    for word in title:lower():gmatch("[%w]+") do
        table.insert(titleWords, word)
    end
    local targetWords = {}
    for word in targetName:lower():gmatch("[%w]+") do
        table.insert(targetWords, word)
    end
    if #targetWords == 0 or #targetWords > #titleWords then
        return false
    end

    for startIndex = 1, #titleWords - #targetWords + 1 do
        local matches = true
        for offset, expected in ipairs(targetWords) do
            local actual = titleWords[startIndex + offset - 1]
            local finalWord = offset == #targetWords
            local finalWordMatches = finalWord
                and (actual == expected .. "s"
                    or (allowFirstSeaVariants
                        and trackedTargetMatches(actual, expected, true)))
            if actual ~= expected and not finalWordMatches then
                matches = false
                break
            end
        end
        if matches then
            return true
        end
    end
    return false
end

local function parseMainQuestTitleProgress(title)
    if type(title) ~= "string" then
        return nil
    end
    local currentText, totalText = title:match("%((%d+)%s*/%s*(%d+)%)%s*$")
    local current = tonumber(currentText)
    local total = tonumber(totalText)
    if not current or not total or total <= 0 or current >= total then
        return nil
    end
    return current, total
end

local function findEligibleQuestTarget(
    self,
    guideData,
    targetName,
    progressTotal,
    allowFirstSeaActiveQuest
)
    local level = self:GetPlayerLevel()
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil
    end

    local firstSeaMatches = {}
    -- Selection exclusions do not hide a separately verified active First Sea quest.
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and (allowFirstSeaActiveQuest or not excludedQuestNames[npcEntry.InternalQuestName])
            and type(npcEntry.Levels) == "table"
        then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericLevel = tonumber(requiredLevel)
                    local quest = questGroup[questId]
                    if numericLevel and numericLevel >= 0 and numericLevel <= level
                        and type(quest) == "table" and type(quest.Task) == "table"
                    then
                        if allowFirstSeaActiveQuest then
                            for mobName, count in pairs(quest.Task) do
                                local numericCount = tonumber(count)
                                if type(mobName) == "string"
                                    and trackedTargetMatches(mobName, targetName, true)
                                    and numericCount == progressTotal and numericCount > 1
                                then
                                    firstSeaMatches[mobName] = true
                                end
                            end
                        else
                            local mobName, count = next(quest.Task)
                            local numericCount = tonumber(count)
                            if mobName == targetName and numericCount == progressTotal
                                and numericCount > 1
                            then
                                return mobName
                            end
                        end
                    end
                end
            end
        end
    end

    if allowFirstSeaActiveQuest then
        local matchedTarget = nil
        for mobName in pairs(firstSeaMatches) do
            if matchedTarget then
                return nil
            end
            matchedTarget = mobName
        end
        return matchedTarget
    end
    return nil
end

local function findEligibleTargetFromTitle(self, guideData, title, progressTotal)
    local level = self:GetPlayerLevel()
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil, "quest catalog or eligible NPC list is unavailable"
    end

    local bestTarget, bestLength, ambiguous = nil, 0, false
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and not excludedQuestNames[npcEntry.InternalQuestName]
            and type(npcEntry.Levels) == "table"
        then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericLevel = tonumber(requiredLevel)
                    local quest = questGroup[questId]
                    if numericLevel and numericLevel >= 0 and numericLevel <= level
                        and type(quest) == "table" and type(quest.Task) == "table"
                    then
                        for mobName, count in pairs(quest.Task) do
                            local numericCount = tonumber(count)
                            if type(mobName) == "string" and numericCount and numericCount > 1
                                and numericCount == progressTotal
                                and titleContainsTarget(title, mobName)
                            then
                                local nameLength = #mobName
                                if nameLength > bestLength then
                                    bestTarget, bestLength, ambiguous = mobName, nameLength, false
                                elseif nameLength == bestLength and bestTarget ~= mobName then
                                    ambiguous = true
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if ambiguous then
        return nil, "visible quest title matches multiple catalog targets"
    end
    if not bestTarget then
        return nil, "visible quest title does not map to a level-eligible catalog target"
    end
    return bestTarget
end

local function readTrackedQuestTarget(self, guideData, isFirstSea)
    local ok, targetName = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return nil
        end

        local playerGui = compatibility:GetPlayerGui()
        local trackedQuestFrame = playerGui and playerGui:FindFirstChild("TrackedQuestFrame")
        if not trackedQuestFrame or not trackedQuestFrame:IsA("ScreenGui")
            or not trackedQuestFrame.Enabled
        then
            return nil
        end

        local frame = trackedQuestFrame:FindFirstChild("Frame")
        local header = frame and frame:FindFirstChild("header")
        local titleLabel = header and header:FindFirstChild("textLabel")
        local description = frame and frame:FindFirstChild("description")
        local progressLabel = frame and frame:FindFirstChild("progress")
        if isFirstSea
            and (not isVisibleGuiObjectWithin(titleLabel, trackedQuestFrame)
                or not isVisibleGuiObjectWithin(description, trackedQuestFrame)
                or not isVisibleGuiObjectWithin(progressLabel, trackedQuestFrame))
        then
            return nil
        end

        local title = titleLabel and usableTrackedQuestText(
            titleLabel.Text,
            MAX_TRACKED_QUEST_TEXT_LENGTH
        )
        local target = description and usableTrackedQuestText(
            description.Text,
            MAX_TRACKED_QUEST_TEXT_LENGTH
        )
        local progressText = progressLabel and progressLabel.Text
        if not title or not target then
            return nil
        end
        if isFirstSea and not titleContainsTarget(title, target, true) then
            return nil
        end
        local progressCurrent, progressTotal = parseTrackedQuestProgress(progressText)
        if progressCurrent == nil or progressTotal == nil then
            return nil
        end

        return findEligibleQuestTarget(self, guideData, target, progressTotal, isFirstSea == true)
    end)

    if not ok then
        return nil
    end
    return targetName
end

local function visibleDialogueText(label, playerGui)
    local isTextLabel = label and (
        label:IsA("TextLabel")
            or label:IsA("TextButton")
            or label:IsA("TextBox")
    )
    if not isTextLabel or not isVisibleGuiObjectWithin(label, playerGui)
        or type(label.Text) ~= "string"
    then
        return nil
    end

    local text = label.Text:match("^%s*(.-)%s*$")
    if text == "" or #text > 64 then
        return nil
    end
    return text
end

local function matchesQuestDialogueTaskTitle(titleText, quests)
    if type(titleText) ~= "string" or type(quests) ~= "table" then
        return false
    end
    local normalizedTitle = normalizeQuestTargetName(titleText)
    if not normalizedTitle then
        return false
    end

    for _, questGroup in pairs(quests) do
        if type(questGroup) == "table" then
            for _, questData in pairs(questGroup) do
                local task = type(questData) == "table" and questData.Task or nil
                if type(task) == "table" then
                    local targetName, count = next(task)
                    local numericCount = tonumber(count)
                    if type(targetName) == "string" and numericCount and numericCount > 0 then
                        local expectedTitle = "Defeat "
                            .. tostring(numericCount)
                            .. " "
                            .. targetName
                        if normalizeQuestTargetName(expectedTitle) == normalizedTitle then
                            return true
                        end
                    end
                end
            end
        end
    end
    return false
end

local function hasVisibleQuestGiverDialogue(playerGui, guideData, quests)
    local dialogueGui = playerGui and playerGui:FindFirstChild("DialogueGui")
    local titleFrame = dialogueGui
        and dialogueGui:FindFirstChild("dialogueTitleFrame", true)
    if not titleFrame or not isVisibleGuiObjectWithin(titleFrame, playerGui) then
        return false
    end

    local subtitle = titleFrame and titleFrame:FindFirstChild("subtitle")
    local titleLabel = subtitle and subtitle:FindFirstChild("title")
    local titleText = visibleDialogueText(titleLabel, playerGui)
    if titleText and string.lower(titleText) == "quest giver" then
        return true
    end

    -- Some quest-giver pages show the NPC name instead of the generic role
    -- title. Match that label against the live quest catalog.
    local speakerLabel = titleFrame:FindFirstChild("name")
    local speakerText = visibleDialogueText(speakerLabel, playerGui)
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) == "table" then
        for _, npcEntry in pairs(npcList) do
            local npcName = type(npcEntry) == "table" and npcEntry.NPCName or nil
            if type(npcName) == "string" then
                npcName = npcName:match("^%s*(.-)%s*$")
                local normalizedNpcName = string.lower(npcName)
                if (titleText and string.lower(titleText) == normalizedNpcName)
                    or (speakerText and string.lower(speakerText) == normalizedNpcName)
                then
                    return true
                end
            end
        end
    end

    -- The second page uses a generic Rewards heading and puts the selected
    -- quest title in the speaker slot (for example, "Defeat 8 Pirates").
    -- Match that title against quest tasks, without accepting the quest.
    return titleText
        and string.lower(titleText) == "rewards"
        and matchesQuestDialogueTaskTitle(speakerText, quests)
        or false
end

local function readFirstSeaQuestHud(self, guideData)
    local ok, state, targetName, reason = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return "unknown", nil, "PlayerGui reader is unavailable"
        end

        local playerGui = compatibility:GetPlayerGui()
        local main = playerGui and playerGui:FindFirstChild("Main")
        if not main then
            return "unknown", nil, "PlayerGui.Main is unavailable"
        end
        if main:IsA("ScreenGui") and not main.Enabled then
            if hasVisibleQuestGiverDialogue(playerGui, guideData, self.Quests) then
                return "none", nil,
                    "visible Quest Giver dialogue; StartQuest still requires active-state confirmation"
            end
            return "unknown", nil,
                "PlayerGui.Main ScreenGui is disabled; no visible Quest Giver dialogue was found"
        end

        local questFrame = main:FindFirstChild("Quest")
        if not questFrame or not questFrame:IsA("GuiObject") then
            return "unknown", nil, "PlayerGui.Main.Quest is unavailable"
        end
        if not questFrame.Visible then
            return "none", nil, "PlayerGui.Main.Quest.Visible is false"
        end

        local container = questFrame:FindFirstChild("Container")
        local questTitle = container and container:FindFirstChild("QuestTitle")
        local titleLabel = questTitle and questTitle:FindFirstChild("Title")
        local titleIsText = titleLabel and (
            titleLabel:IsA("TextLabel")
                or titleLabel:IsA("TextButton")
                or titleLabel:IsA("TextBox")
        )
        if not titleIsText or not titleLabel.Visible
            or not container or (container:IsA("GuiObject") and not container.Visible)
            or not questTitle or (questTitle:IsA("GuiObject") and not questTitle.Visible)
        then
            return "active-unknown", nil, "visible quest panel has no visible readable title label"
        end

        local title = usableTrackedQuestText(titleLabel.Text, MAX_MAIN_QUEST_TITLE_LENGTH)
        if not title then
            return "active-unknown", nil, "visible quest panel title is empty or malformed"
        end
        local _, progressTotal = parseMainQuestTitleProgress(title)
        if not progressTotal then
            return "active-unknown", nil, "visible quest title has no valid incomplete current/total progress"
        end
        local mappedTarget, mappingError = findEligibleTargetFromTitle(
            self,
            guideData,
            title,
            progressTotal
        )
        if not mappedTarget then
            return "active-unknown", nil, mappingError
        end
        return "active", mappedTarget,
            "visible Main.Quest title/progress maps to the level-eligible quest catalog"
    end)

    if not ok then
        return "unknown", nil, "First Sea quest HUD read failed safely"
    end
    return state, targetName, reason
end

function QuestService.new(compatibility)
    local quests, guide, loadError = compatibility:GetQuestModules()
    if not quests then
        return nil, loadError
    end
    return setmetatable({
        Compatibility = compatibility,
        Player = compatibility.Player,
        Quests = quests,
        Guide = guide,
    }, QuestService)
end

function QuestService:GetPlayerLevel()
    local data = self.Player and self.Player:FindFirstChild("Data")
    local level = data and data:FindFirstChild("Level")
    return level and tonumber(level.Value)
end

function QuestService:IsQuestGiverDialogueOpen()
    local ok, isOpen = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return false
        end
        local guideData = self.Guide and self.Guide.Data
        return hasVisibleQuestGiverDialogue(
            compatibility:GetPlayerGui(),
            guideData,
            self.Quests
        )
    end)
    return ok and isOpen == true
end

function QuestService:GetActiveQuestState()
    local guideData = self.Guide and self.Guide.Data
    local questData = type(guideData) == "table" and guideData.QuestData or nil
    if type(questData) == "table" and type(questData.Task) == "table" then
        local targetName = next(questData.Task)
        if type(targetName) == "string" and targetName ~= "" then
            return "active", targetName, "GuideModule.Data.QuestData.Task"
        end
    end

    local firstSea = false
    if self.Compatibility and type(self.Compatibility.IsFirstSea) == "function" then
        local seaReadOk, isFirstSea = pcall(self.Compatibility.IsFirstSea, self.Compatibility)
        firstSea = seaReadOk and isFirstSea == true
    end

    local trackedTarget = readTrackedQuestTarget(self, guideData, firstSea)
    if trackedTarget then
        return "active", trackedTarget, "TrackedQuestFrame title/target/progress mapped to quest catalog"
    end

    if firstSea then
        local hudState, hudTarget, hudReason = readFirstSeaQuestHud(self, guideData)
        return hudState, hudTarget, hudReason
    end

    if type(guideData) ~= "table" then
        return "unknown", nil, "GuideModule.Data is unavailable"
    end
    if questData == nil then
        return "none", nil, "GuideModule.Data.QuestData is absent"
    end
    if type(questData) ~= "table" or type(questData.Task) ~= "table" then
        return "unknown", nil, "GuideModule.Data.QuestData.Task is not a table"
    end
    return "active-unknown", nil, "GuideModule exposes a quest record without a readable task"
end

function QuestService:SelectLevelQuest()
    local level = self:GetPlayerLevel()
    local guideData = self.Guide and self.Guide.Data
    local npcList = guideData and guideData.NPCList
    if not level or type(npcList) ~= "table" then
        return nil, "Player level or GuideModule.Data.NPCList is unavailable"
    end

    local bestLevel = 0
    local bestCandidate = nil
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table" and not excludedQuestNames[npcEntry.InternalQuestName] then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(npcEntry.Levels) == "table" and type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local quest = questGroup[questId]
                    local numericLevel = tonumber(requiredLevel)
                    if type(quest) == "table"
                        and type(quest.Task) == "table"
                        and numericLevel
                        and numericLevel <= level
                        and numericLevel >= bestLevel
                    then
                        local mobName, count = next(quest.Task)
                        local numericCount = tonumber(count)
                        if type(mobName) == "string" and numericCount and numericCount > 1 then
                            bestCandidate = {
                                Level = numericLevel,
                                Name = npcEntry.NPCName,
                                QuestName = npcEntry.InternalQuestName,
                                Pos = npcEntry.Position,
                                Id = questId,
                                Mob = mobName,
                            }

                            local activeState, activeTarget = self:GetActiveQuestState()
                            local numericQuestId = tonumber(questId)
                            if activeState == "active"
                                and activeTarget == mobName
                                and numericQuestId
                                and numericQuestId > 1
                            then
                                local previousQuest = questGroup[numericQuestId - 1]
                                if previousQuest and type(previousQuest.Task) == "table" then
                                    for previousMob, previousCount in pairs(previousQuest.Task) do
                                        if previousMob ~= activeTarget
                                            and tonumber(previousCount)
                                            and tonumber(previousCount) > 1
                                        then
                                            bestCandidate.Mob = previousMob
                                            bestCandidate.Id = numericQuestId - 1
                                            break
                                        end
                                    end
                                end
                            end
                            bestLevel = numericLevel
                        end
                    end
                end
            end
        end
    end

    if not bestCandidate then
        return nil, "No eligible level-based quest candidate"
    end
    return bestCandidate
end

function QuestService:GetQuestTargets(prefix, maximumLevel)
    if type(prefix) ~= "string" or prefix == "" then
        return nil, "Quest family prefix is invalid"
    end
    local levelLimit = tonumber(maximumLevel)
    if not levelLimit then
        return nil, "Player level is unavailable for quest target lookup"
    end

    local guideData = self.Guide and self.Guide.Data
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) ~= "table" then
        return nil, "GuideModule.Data.NPCList is unavailable"
    end

    local targets = {}
    local seen = {}
    for _, npcEntry in pairs(npcList) do
        local questName = type(npcEntry) == "table" and npcEntry.InternalQuestName or nil
        local questGroup = type(questName) == "string"
            and questName:sub(1, #prefix) == prefix
            and self.Quests
            and self.Quests[questName]
            or nil
        if type(questGroup) == "table" and type(npcEntry.Levels) == "table" then
            for questId, requiredLevel in pairs(npcEntry.Levels) do
                local levelRequired = tonumber(requiredLevel)
                local quest = questGroup[questId] or questGroup[tostring(questId)]
                local task = type(quest) == "table" and quest.Task or nil
                if levelRequired and levelRequired <= levelLimit and type(task) == "table" then
                    for targetName, count in pairs(task) do
                        if type(targetName) == "string"
                            and targetName ~= ""
                            and tonumber(count)
                            and tonumber(count) > 0
                            and not seen[targetName]
                        then
                            seen[targetName] = true
                            table.insert(targets, targetName)
                        end
                    end
                end
            end
        end
    end

    table.sort(targets)
    if #targets == 0 then
        return nil, "No eligible targets were found in quest family " .. prefix
    end
    return targets
end

function QuestService:SelectQuest(questName, questId, minimumLevel)
    if type(questName) ~= "string" or questName == "" or questId == nil then
        return nil, "Special quest identity is invalid"
    end
    local level = self:GetPlayerLevel()
    local minimum = tonumber(minimumLevel)
    if not level or not minimum then
        return nil, "Player level or special quest level is unavailable"
    end
    if level < minimum then
        return nil, "Player level is below the selected mode's minimum"
    end

    local questGroup = self.Quests and self.Quests[questName]
    local quest = type(questGroup) == "table"
        and (questGroup[questId] or questGroup[tostring(questId)])
        or nil
    if type(quest) ~= "table" or type(quest.Task) ~= "table" then
        return nil, "The selected quest is missing from the live quest catalog"
    end
    local mobName, count = next(quest.Task)
    if type(mobName) ~= "string" or not tonumber(count) or tonumber(count) <= 0 then
        return nil, "The selected quest has no readable target"
    end

    local guideData = self.Guide and self.Guide.Data
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) ~= "table" then
        return nil, "GuideModule.Data.NPCList is unavailable"
    end

    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and npcEntry.InternalQuestName == questName
            and type(npcEntry.Levels) == "table"
        then
            for listedQuestId, requiredLevel in pairs(npcEntry.Levels) do
                local npcLevel = tonumber(requiredLevel)
                if tostring(listedQuestId) == tostring(questId)
                    and npcLevel
                    and npcLevel <= level
                then
                    local catalogLevel = tonumber(quest.LevelReq)
                    local candidateLevel = math.max(npcLevel, catalogLevel or 0)
                    if candidateLevel > level then
                        return nil, "Player level does not satisfy the live quest catalog"
                    end
                    return {
                        Level = candidateLevel,
                        Name = npcEntry.NPCName,
                        QuestName = questName,
                        Pos = npcEntry.Position,
                        Id = questId,
                        Mob = mobName,
                    }
                end
            end
        end
    end
    return nil, "GuideModule does not expose the selected quest giver and position"
end

function QuestService:RequestStart(candidate)
    self.LastStartDiagnostic = {
        Stage = "pcall_not_reached",
        PcallSucceeded = nil,
        ResultType = "n/a",
        ResultSummary = "not returned",
    }
    if type(candidate) ~= "table" or not candidate.QuestName or candidate.Id == nil then
        self.LastStartDiagnostic.Stage = "candidate_invalid"
        return false, "Quest candidate is incomplete"
    end

    local commF, remoteError = self.Compatibility:GetCommF()
    if not commF then
        self.LastStartDiagnostic.Stage = "remote_unavailable"
        return false, remoteError
    end
    local ok, result = pcall(function()
        return commF:InvokeServer("StartQuest", tostring(candidate.QuestName), candidate.Id)
    end)
    pcall(function()
        self.LastStartDiagnostic = {
            Stage = "pcall_completed",
            PcallSucceeded = ok,
            ResultType = tostring(typeof(result)),
            ResultSummary = diagnosticScalarRepresentation(result),
        }
    end)
    if not ok then
        return false, tostring(result)
    end

    -- BNN ignores this return value; acceptance is confirmed separately through QuestData.Task.
    return true, result
end

return QuestService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
end

__bundleFactories["CustomHub.Features.Farm.EnemyService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
local EnemyService = {}
EnemyService.__index = EnemyService

local HIDDEN_SPAWN_REFRESH_INTERVAL = 5
local HIDDEN_SPAWN_RETRY_INTERVAL = 10
local HIDDEN_SPAWN_SCAN_CHUNK_SIZE = 64
local BRING_MOB_COOLDOWN = 0.75
local BRING_MOB_MAX_DISTANCE = 200
local BRING_MOB_PLAYER_RANGE = 50
local BRING_MOB_OTHER_PLAYER_RANGE = 300
local BRING_MOB_MIN_COUNT = 2
local BRING_MOB_MAX_COUNT = 6
local BRING_MOB_MAX_MOVES_PER_CALL = 2

local function disconnect(connection)
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
    end
end

local function singularizeEnemyWord(word)
    if #word > 3 and word:sub(-3) == "ies" then
        local stem = word:sub(1, -4)
        local lastStemCharacter = stem:sub(-1)
        if lastStemCharacter ~= "" and not lastStemCharacter:match("[aeiou]") then
            return stem .. "y"
        end
    end

    if #word > 4 and word:sub(-2) == "es" then
        local stem = word:sub(1, -3)
        if stem:sub(-1) == "s" or stem:sub(-1) == "x" or stem:sub(-1) == "z"
            or stem:sub(-2) == "ch" or stem:sub(-2) == "sh"
        then
            return stem
        end
    end

    local ending = word:sub(-2)
    if #word > 2 and word:sub(-1) == "s"
        and ending ~= "ss" and ending ~= "us" and ending ~= "is"
    then
        return word:sub(1, -2)
    end
    return word
end

local function normalizeEnemyName(name)
    if type(name) ~= "string" or #name == 0 then
        return nil
    end

    local baseName = name:lower():gsub("%s+%p?lv%.?%s*%d+%p?%s*$", "")
    local words = {}
    for word in baseName:gmatch("[%w]+") do
        table.insert(words, word)
    end
    if #words == 0 then
        return nil
    end

    words[#words] = singularizeEnemyWord(words[#words])
    return table.concat(words, " ")
end

local function normalizeTargetNames(targetNames)
    local normalized = {}
    if type(targetNames) == "string" then
        local name = normalizeEnemyName(targetNames)
        if name then
            table.insert(normalized, name)
        end
    elseif type(targetNames) == "table" then
        for _, targetName in ipairs(targetNames) do
            local name = normalizeEnemyName(targetName)
            if name then
                table.insert(normalized, name)
            end
        end
    end
    return normalized
end

local function isDescendantOf(instance, container)
    if not instance or not container then
        return false
    end
    local ok, result = pcall(function()
        return instance:IsDescendantOf(container)
    end)
    return ok and result == true
end

local function matchesSpawnName(spawnName, normalizedTargets)
    local normalizedName = normalizeEnemyName(spawnName)
    if not normalizedName then
        return false
    end
    for _, normalizedTarget in ipairs(normalizedTargets or {}) do
        if normalizedName == normalizedTarget then
            return true
        end
    end
    return false
end

local function matchedTargetName(spawnName, targetNames, normalizedTargets)
    for index, normalizedTarget in ipairs(normalizedTargets) do
        if normalizeEnemyName(spawnName) == normalizedTarget then
            if type(targetNames) == "string" then
                return targetNames
            end
            return targetNames[index]
        end
    end
    return nil
end

local function addNameIndexEntry(index, namesByInstance, instance)
    local normalizedName = normalizeEnemyName(instance.Name)
    if not normalizedName then
        namesByInstance[instance] = nil
        return
    end

    local bucket = index[normalizedName]
    if not bucket then
        bucket = setmetatable({}, { __mode = "k" })
        index[normalizedName] = bucket
    end
    bucket[instance] = true
    namesByInstance[instance] = normalizedName
end

local function removeNameIndexEntry(index, namesByInstance, instance)
    local normalizedName = namesByInstance[instance]
    local bucket = normalizedName and index[normalizedName]
    if bucket then
        bucket[instance] = nil
        if next(bucket) == nil then
            index[normalizedName] = nil
        end
    end
    namesByInstance[instance] = nil
end

function EnemyService.new(compatibility)
    return setmetatable({
        Compatibility = compatibility,
        Workspace = compatibility.Workspace,
        CollisionPartsByTarget = setmetatable({}, { __mode = "k" }),
        IgnoredSpawns = {},
        HiddenSpawnCache = nil,
        PreparedTargets = setmetatable({}, { __mode = "k" }),
        EnemyModels = setmetatable({}, { __mode = "k" }),
        EnemyModelsByName = {},
        EnemyModelNames = setmetatable({}, { __mode = "k" }),
        EnemyNameConnections = setmetatable({}, { __mode = "k" }),
        SpawnMarkers = setmetatable({}, { __mode = "k" }),
        SpawnMarkersByName = {},
        SpawnMarkerNames = setmetatable({}, { __mode = "k" }),
        BringMobNextAt = 0,
        BringMobTarget = nil,
    }, EnemyService)
end

function EnemyService:_GetEnemySpawnsFolder()
    local worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin")
    if not worldOrigin then
        worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin", true)
    end
    if not worldOrigin then
        return self.Workspace:FindFirstChild("EnemySpawns", true)
    end

    local enemySpawns = worldOrigin:FindFirstChild("EnemySpawns")
    if not enemySpawns then
        enemySpawns = worldOrigin:FindFirstChild("EnemySpawns", true)
    end
    if not enemySpawns then
        enemySpawns = self.Workspace:FindFirstChild("EnemySpawns", true)
    end
    return enemySpawns
end

function EnemyService:_GetEnemyModelIndex()
    local enemies = self.Workspace:FindFirstChild("Enemies")
    if not enemies then
        enemies = self.Workspace:FindFirstChild("Enemies", true)
    end
    if enemies == self.EnemyContainer then
        return self.EnemyModels, enemies
    end

    disconnect(self.EnemyAddedConnection)
    disconnect(self.EnemyRemovingConnection)
    for _, connection in pairs(self.EnemyNameConnections) do
        disconnect(connection)
    end
    self.EnemyAddedConnection = nil
    self.EnemyRemovingConnection = nil
    self.EnemyContainer = enemies
    self.EnemyModels = setmetatable({}, { __mode = "k" })
    self.EnemyModelsByName = {}
    self.EnemyModelNames = setmetatable({}, { __mode = "k" })
    self.EnemyNameConnections = setmetatable({}, { __mode = "k" })
    if not enemies then
        return self.EnemyModels, nil
    end

    for _, instance in ipairs(enemies:GetDescendants()) do
        self:_IndexEnemyModel(instance)
    end
    self.EnemyAddedConnection = enemies.DescendantAdded:Connect(function(instance)
        self:_IndexEnemyModel(instance)
    end)
    self.EnemyRemovingConnection = enemies.DescendantRemoving:Connect(function(instance)
        self:_UnindexEnemyModel(instance)
    end)
    return self.EnemyModels, enemies
end

function EnemyService:_IndexEnemyModel(model)
    if not model:IsA("Model") then
        return
    end

    self.EnemyModels[model] = true
    removeNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    addNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    if self.EnemyNameConnections[model] then
        return
    end

    self.EnemyNameConnections[model] = model:GetPropertyChangedSignal("Name"):Connect(function()
        if not self.EnemyModels[model] then
            return
        end
        removeNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
        addNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    end)
end

function EnemyService:_UnindexEnemyModel(model)
    if not model:IsA("Model") then
        return
    end
    self.EnemyModels[model] = nil
    removeNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    disconnect(self.EnemyNameConnections[model])
    self.EnemyNameConnections[model] = nil
end

function EnemyService:_GetSpawnMarkerIndex()
    local enemySpawns = self:_GetEnemySpawnsFolder()
    if enemySpawns == self.SpawnContainer then
        return self.SpawnMarkers, enemySpawns
    end

    disconnect(self.SpawnAddedConnection)
    disconnect(self.SpawnRemovingConnection)
    self.SpawnAddedConnection = nil
    self.SpawnRemovingConnection = nil
    self.SpawnContainer = enemySpawns
    self.SpawnMarkers = setmetatable({}, { __mode = "k" })
    self.SpawnMarkersByName = {}
    self.SpawnMarkerNames = setmetatable({}, { __mode = "k" })
    if not enemySpawns then
        return self.SpawnMarkers, nil
    end

    for _, instance in ipairs(enemySpawns:GetDescendants()) do
        self:_IndexSpawnMarker(instance)
    end
    self.SpawnAddedConnection = enemySpawns.DescendantAdded:Connect(function(instance)
        self:_IndexSpawnMarker(instance)
    end)
    self.SpawnRemovingConnection = enemySpawns.DescendantRemoving:Connect(function(instance)
        self:_UnindexSpawnMarker(instance)
    end)
    return self.SpawnMarkers, enemySpawns
end

function EnemyService:_IndexSpawnMarker(spawnPart)
    if not spawnPart:IsA("BasePart") then
        return
    end
    self.SpawnMarkers[spawnPart] = true
    removeNameIndexEntry(self.SpawnMarkersByName, self.SpawnMarkerNames, spawnPart)
    addNameIndexEntry(self.SpawnMarkersByName, self.SpawnMarkerNames, spawnPart)
end

function EnemyService:_UnindexSpawnMarker(spawnPart)
    if not spawnPart:IsA("BasePart") then
        return
    end
    self.SpawnMarkers[spawnPart] = nil
    removeNameIndexEntry(self.SpawnMarkersByName, self.SpawnMarkerNames, spawnPart)
end

function EnemyService:_RefreshHiddenSpawnCache()
    local now = os.clock()
    local current = self.HiddenSpawnCache
    if current and (current.Loading or now < current.ExpiresAt) then
        return current
    end

    local cache = {
        Parts = {},
        ByName = {},
        Available = false,
        Loading = true,
        ExpiresAt = math.huge,
    }
    self.HiddenSpawnCache = cache

    local function markUnavailable()
        if self.HiddenSpawnCache == cache then
            cache.Available = false
            cache.Loading = false
            cache.ExpiresAt = os.clock() + HIDDEN_SPAWN_RETRY_INTERVAL
        end
    end

    task.defer(function()
        local getter = self.Compatibility and self.Compatibility.GetUnparentedInstances
        if type(getter) ~= "function" then
            markUnavailable()
            return
        end

        local callOk, instances = pcall(getter, self.Compatibility)
        if not callOk or type(instances) ~= "table" or self.HiddenSpawnCache ~= cache then
            markUnavailable()
            return
        end

        cache.Available = true
        local scanned = 0
        for _, instance in pairs(instances) do
            if self.HiddenSpawnCache ~= cache then
                return
            end

            local readOk, isBasePart, name, parent = pcall(function()
                return instance:IsA("BasePart"), instance.Name, instance.Parent
            end)
            if readOk and isBasePart and parent == nil and type(name) == "string" then
                cache.Parts[instance] = name
                local normalizedName = normalizeEnemyName(name)
                if normalizedName then
                    local matches = cache.ByName[normalizedName]
                    if not matches then
                        matches = {}
                        cache.ByName[normalizedName] = matches
                    end
                    table.insert(matches, instance)
                end
            end

            scanned += 1
            if scanned % HIDDEN_SPAWN_SCAN_CHUNK_SIZE == 0 then
                task.wait()
            end
        end

        if self.HiddenSpawnCache == cache then
            cache.Loading = false
            cache.ExpiresAt = os.clock() + HIDDEN_SPAWN_REFRESH_INTERVAL
        end
    end)

    return cache
end

function EnemyService:_PruneIgnoredSpawns(enemySpawns, hiddenCache, targetName)
    local normalizedTarget = normalizeTargetNames(targetName)
    for spawnPart in pairs(self.IgnoredSpawns) do
        local readOk, isBasePart, name, parent = pcall(function()
            return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent
        end)
        local matchingName = readOk
            and isBasePart
            and type(name) == "string"
            and matchesSpawnName(name, normalizedTarget)
        local replicated = matchingName
            and enemySpawns ~= nil
            and parent ~= nil
            and isDescendantOf(spawnPart, enemySpawns)
        local hidden = matchingName
            and parent == nil
            and hiddenCache.Available
            and hiddenCache.Parts[spawnPart] == name
        if not replicated and not hidden then
            self.IgnoredSpawns[spawnPart] = nil
        end
    end
end

function EnemyService:IsAlive(model)
    if not model or not model.Parent then
        return false
    end
    local root = model:FindFirstChild("HumanoidRootPart")
    local humanoid = model:FindFirstChildWhichIsA("Humanoid")
    return root ~= nil and humanoid ~= nil and humanoid.Health > 0
end

function EnemyService:FindNearest(targetName, origin)
    local enemyModels, enemies = self:_GetEnemyModelIndex()
    local normalizedTargets = normalizeTargetNames(targetName)
    if not enemies or #normalizedTargets == 0 or not origin then
        return nil
    end

    local nearest, nearestDistance = nil, math.huge
    local seen = {}
    for _, normalizedName in ipairs(normalizedTargets) do
        for enemy in pairs(self.EnemyModelsByName[normalizedName] or {}) do
            if not seen[enemy] then
                seen[enemy] = true
                if enemyModels[enemy] and isDescendantOf(enemy, enemies) then
                    local root = enemy:FindFirstChild("HumanoidRootPart")
                    local humanoid = enemy:FindFirstChildWhichIsA("Humanoid")
                    if root and humanoid and humanoid.Health > 0 then
                        local distance = (root.Position - origin).Magnitude
                        if distance < nearestDistance then
                            nearest, nearestDistance = enemy, distance
                        end
                    end
                end
            end
        end
    end
    return nearest, nearestDistance
end

function EnemyService:FindNearestInRange(origin, maxDistance)
    if typeof(origin) ~= "Vector3" then
        return nil
    end
    local radius = tonumber(maxDistance)
    if not radius or radius < 0 or radius ~= radius or math.abs(radius) == math.huge then
        return nil
    end

    local enemyModels, enemies = self:_GetEnemyModelIndex()
    if not enemies then
        return nil
    end

    local nearest, nearestDistance = nil, radius
    for enemy in pairs(enemyModels) do
        if isDescendantOf(enemy, enemies) and self:IsAlive(enemy) then
            local distance = (enemy.HumanoidRootPart.Position - origin).Magnitude
            if distance <= nearestDistance then
                nearest, nearestDistance = enemy, distance
            end
        end
    end
    return nearest, nearestDistance
end

function EnemyService:FindSpawn(targetName, origin)
    local diagnostic = {
        TargetName = type(targetName) == "string" and targetName or "multiple quest targets",
        EnemySpawnsContainerFound = false,
        NormalMarkerFound = false,
        HiddenMarkerFound = false,
        HiddenDiscoveryAvailable = false,
        HiddenDiscoveryChecked = false,
        SelectedSource = "none",
        SelectedName = nil,
        MatchedTarget = nil,
        SelectedDistance = nil,
    }
    local normalizedTarget = normalizeTargetNames(targetName)
    if #normalizedTarget == 0 then
        return nil, false, diagnostic
    end

    local _, enemySpawns = self:_GetSpawnMarkerIndex()
    local now = os.clock()
    local hiddenCache = self.HiddenSpawnCache
    if hiddenCache and not hiddenCache.Loading and now >= hiddenCache.ExpiresAt then
        hiddenCache = nil
    end
    diagnostic.EnemySpawnsContainerFound = enemySpawns ~= nil
    diagnostic.HiddenDiscoveryChecked = hiddenCache ~= nil
    diagnostic.HiddenDiscoveryAvailable = hiddenCache ~= nil
        and hiddenCache.Available == true
    diagnostic.HiddenDiscoveryLoading = hiddenCache ~= nil
        and hiddenCache.Loading == true
    self:_PruneIgnoredSpawns(
        enemySpawns,
        hiddenCache or { Available = false, Parts = {} },
        targetName
    )

    local hasMatchingSpawn = false
    local nearest, nearestDistance = nil, math.huge
    local function considerSpawn(spawnPart, expectedParent, expectedName, source)
        local readOk, isBasePart, name, parent, position = pcall(function()
            return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent, spawnPart.Position
        end)
        local inExpectedContainer = source == "EnemySpawns"
            and isDescendantOf(spawnPart, expectedParent)
        local inHiddenCache = source == "unparented-cache" and parent == nil
        if not readOk
            or not isBasePart
            or (source == "EnemySpawns" and not inExpectedContainer)
            or (source == "unparented-cache" and not inHiddenCache)
            or type(name) ~= "string"
            or (expectedName and name ~= expectedName)
            or not matchesSpawnName(name, normalizedTarget)
        then
            return
        end

        hasMatchingSpawn = true
        if source == "EnemySpawns" then
            diagnostic.NormalMarkerFound = true
        elseif source == "unparented-cache" then
            diagnostic.HiddenMarkerFound = true
        end
        if self.IgnoredSpawns[spawnPart] then
            return
        end
        local distance = typeof(origin) == "Vector3"
            and (position - origin).Magnitude
            or 0
        if distance < nearestDistance then
            nearest, nearestDistance = spawnPart, distance
            diagnostic.SelectedSource = source
            diagnostic.SelectedName = name
            diagnostic.MatchedTarget = matchedTargetName(name, targetName, normalizedTarget)
            diagnostic.SelectedDistance = distance
        end
    end

    if enemySpawns then
        local seenNormal = {}
        for _, normalizedName in ipairs(normalizedTarget) do
            for spawnPart in pairs(self.SpawnMarkersByName[normalizedName] or {}) do
                if not seenNormal[spawnPart] then
                    seenNormal[spawnPart] = true
                    considerSpawn(spawnPart, enemySpawns, nil, "EnemySpawns")
                end
            end
        end
    end

    -- Only enumerate all unparented runtime instances if the normal marker index
    -- cannot provide a candidate. A valid cached fallback remains usable meanwhile.
    if not hiddenCache and not nearest then
        hiddenCache = self:_RefreshHiddenSpawnCache()
        diagnostic.HiddenDiscoveryChecked = true
        diagnostic.HiddenDiscoveryAvailable = hiddenCache.Available == true
        diagnostic.HiddenDiscoveryLoading = hiddenCache.Loading == true
    end

    if hiddenCache
        and hiddenCache.Available
        and not hiddenCache.Loading
        and os.clock() < hiddenCache.ExpiresAt
    then
        local seenHidden = {}
        for _, normalizedName in ipairs(normalizedTarget) do
            for _, spawnPart in ipairs(hiddenCache.ByName[normalizedName] or {}) do
                local cachedName = hiddenCache.Parts[spawnPart]
                if cachedName and not seenHidden[spawnPart] then
                    seenHidden[spawnPart] = true
                    considerSpawn(spawnPart, nil, cachedName, "unparented-cache")
                end
            end
        end
    end

    if nearest then
        return nearest, false, diagnostic, diagnostic.MatchedTarget
    end
    return nil, hasMatchingSpawn, diagnostic, nil
end

function EnemyService:IsSpawnAvailable(spawnPart, targetName)
    if not spawnPart then
        return false
    end
    local readOk, isBasePart, name, parent = pcall(function()
        return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent
    end)
    if not readOk
        or not isBasePart
        or type(name) ~= "string"
        or self.IgnoredSpawns[spawnPart]
    then
        return false
    end

    local normalizedTarget = normalizeTargetNames(targetName)
    if not matchesSpawnName(name, normalizedTarget) then
        return false
    end

    local enemySpawns = self:_GetEnemySpawnsFolder()
    if enemySpawns ~= nil and parent ~= nil and isDescendantOf(spawnPart, enemySpawns) then
        return true
    end

    local hiddenCache = self.HiddenSpawnCache
    return parent == nil
        and hiddenCache ~= nil
        and hiddenCache.Available
        and os.clock() < hiddenCache.ExpiresAt
        and hiddenCache.Parts[spawnPart] == name
end

function EnemyService:MarkSpawnIgnored(spawnPart, targetName)
    if self:IsSpawnAvailable(spawnPart, targetName) then
        self.IgnoredSpawns[spawnPart] = true
    end
end

function EnemyService:ClearIgnoredSpawns()
    table.clear(self.IgnoredSpawns)
end

function EnemyService:ClearTracking()
    disconnect(self.EnemyAddedConnection)
    disconnect(self.EnemyRemovingConnection)
    disconnect(self.SpawnAddedConnection)
    disconnect(self.SpawnRemovingConnection)
    for _, connection in pairs(self.EnemyNameConnections) do
        disconnect(connection)
    end
    self.EnemyAddedConnection = nil
    self.EnemyRemovingConnection = nil
    self.SpawnAddedConnection = nil
    self.SpawnRemovingConnection = nil
    self.EnemyContainer = nil
    self.SpawnContainer = nil
    self.EnemyModels = setmetatable({}, { __mode = "k" })
    self.EnemyModelsByName = {}
    self.EnemyModelNames = setmetatable({}, { __mode = "k" })
    self.EnemyNameConnections = setmetatable({}, { __mode = "k" })
    self.SpawnMarkers = setmetatable({}, { __mode = "k" })
    self.SpawnMarkersByName = {}
    self.SpawnMarkerNames = setmetatable({}, { __mode = "k" })
    self.HiddenSpawnCache = nil
    self.BringMobNextAt = 0
    self.BringMobTarget = nil
    table.clear(self.PreparedTargets)
end

function EnemyService:_HasNearbyOtherPlayer(position)
    local players = self.Compatibility and self.Compatibility.Players
    local localPlayer = self.Compatibility and self.Compatibility.Player
    if not players or type(players.GetPlayers) ~= "function" then
        return false
    end

    for _, player in ipairs(players:GetPlayers()) do
        if player ~= localPlayer then
            local character = player.Character
            local otherRoot = character and character:FindFirstChild("HumanoidRootPart")
            if otherRoot and otherRoot:IsA("BasePart")
                and (otherRoot.Position - position).Magnitude <= BRING_MOB_OTHER_PLAYER_RANGE
            then
                return true
            end
        end
    end
    return false
end

function EnemyService:BringMatchingMob(target, playerRoot, requestedCount)
    if not self:IsAlive(target) or not playerRoot or not self.EnemyContainer then
        return 0
    end
    local desiredCount = tonumber(requestedCount) or BRING_MOB_MIN_COUNT
    if desiredCount ~= desiredCount or math.abs(desiredCount) == math.huge then
        desiredCount = BRING_MOB_MIN_COUNT
    end
    desiredCount = math.clamp(
        math.floor(desiredCount + 0.5),
        BRING_MOB_MIN_COUNT,
        BRING_MOB_MAX_COUNT
    )

    local targetRoot = target:FindFirstChild("HumanoidRootPart")
    if not targetRoot or not targetRoot:IsA("BasePart")
        or (targetRoot.Position - playerRoot.Position).Magnitude > BRING_MOB_PLAYER_RANGE
    then
        return 0
    end

    local now = os.clock()
    if self.BringMobTarget == target and now < self.BringMobNextAt then
        return 0
    end
    self.BringMobTarget = target
    self.BringMobNextAt = now + BRING_MOB_COOLDOWN

    local normalizedName = normalizeEnemyName(target.Name)
    if not normalizedName then
        return 0
    end
    local bucket = self.EnemyModelsByName[normalizedName] or {}
    local nearbyCount = 1
    local candidates = {}
    local candidateLimit = desiredCount - 1
    for enemy in pairs(bucket) do
        if enemy ~= target
            and enemy.Name == target.Name
            and isDescendantOf(enemy, self.EnemyContainer)
            and not enemy:FindFirstChild("Ignored")
            and self:IsAlive(enemy)
        then
            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
            if enemyRoot and enemyRoot:IsA("BasePart") and not enemyRoot.Anchored then
                local distance = (enemyRoot.Position - targetRoot.Position).Magnitude
                -- This nearby-player check follows the reference hubs' conservative
                -- guard; it is not a guarantee of client network ownership.
                if distance <= 8 then
                    nearbyCount += 1
                elseif distance <= BRING_MOB_MAX_DISTANCE
                    and not self:_HasNearbyOtherPlayer(enemyRoot.Position)
                then
                    local candidate = { Model = enemy, Distance = distance }
                    local insertAt = #candidates + 1
                    while insertAt > 1
                        and candidates[insertAt - 1].Distance > distance
                    do
                        insertAt -= 1
                    end
                    table.insert(candidates, insertAt, candidate)
                    if #candidates > candidateLimit then
                        table.remove(candidates)
                    end
                end
            end
        end
    end

    if nearbyCount >= desiredCount or #candidates == 0 then
        return 0
    end

    -- Honor larger requested groups gradually so one farm tick never moves many NPCs.
    local movesRemaining = math.min(
        desiredCount - nearbyCount,
        BRING_MOB_MAX_MOVES_PER_CALL,
        #candidates
    )
    local movedCount = 0
    for index = 1, movesRemaining do
        local candidateRoot = candidates[index].Model:FindFirstChild("HumanoidRootPart")
        if candidateRoot and candidateRoot:IsA("BasePart") and not candidateRoot.Anchored then
            local moved = pcall(function()
                candidateRoot.CFrame = targetRoot.CFrame * CFrame.new(3 + (index - 1) * 2, 0, 0)
            end)
            if moved then
                movedCount += 1
            end
        end
    end
    return movedCount
end

function EnemyService:PrepareTarget(model, playerRoot)
    if not self:IsAlive(model) or not playerRoot then
        return
    end
    if (model.HumanoidRootPart.Position - playerRoot.Position).Magnitude > 50 then
        return
    end

    if self.PreparedTargets[model] then
        return
    end
    local targetParts = {}
    for _, part in ipairs(model:GetDescendants()) do
        if part:IsA("BasePart") and part.CanCollide then
            targetParts[part] = part.CanCollide
            part.CanCollide = false
        end
    end
    self.CollisionPartsByTarget[model] = targetParts
    self.PreparedTargets[model] = true
end

function EnemyService:RestoreTargetCollision(target)
    if target then
        local targetParts = self.CollisionPartsByTarget[target]
        if targetParts then
            local shouldRestore = target.Parent ~= nil
            if shouldRestore then
                local humanoid = target:FindFirstChildWhichIsA("Humanoid")
                if humanoid and humanoid.Health <= 0 then
                    shouldRestore = false
                end
            end

            if shouldRestore then
                for part, originalCanCollide in pairs(targetParts) do
                    if part.Parent and part.CanCollide ~= originalCanCollide then
                        part.CanCollide = originalCanCollide
                    end
                end
            end
        end
        self.CollisionPartsByTarget[target] = nil
        self.PreparedTargets[target] = nil
        return
    end

    for targetModel, targetParts in pairs(self.CollisionPartsByTarget) do
        for part, originalCanCollide in pairs(targetParts) do
            if part.Parent and part.CanCollide ~= originalCanCollide then
                part.CanCollide = originalCanCollide
            end
        end
        self.CollisionPartsByTarget[targetModel] = nil
    end
    table.clear(self.PreparedTargets)
    table.clear(self.CollisionPartsByTarget)
end

return EnemyService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
end

__bundleFactories["CustomHub.Features.Farm.MovementService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
local MovementService = {}
MovementService.__index = MovementService

local SUBMERGED_REFERENCE = Vector3.new(11538.599609375, -2154.7021484375, 9827.3125)
local SUBMERGED_STAGING = CFrame.new(
    -16269.4082,
    23.9799957,
